}
.dashboard-widget-card.col-span-6,
.dashboard-widget-card[data-widget-cols="6"] {
    grid-column: span 1 / span 1;
}
.dashboard-widget-card.col-span-8,
.dashboard-widget-card[data-widget-cols="8"] {
    grid-column: span 1 / span 1;
}
.dashboard-widget-card.col-span-12,
.dashboard-widget-card[data-widget-cols="12"] {
    grid-column: span 1 / span 1;
}

@media (min-width: 640px) {
