    .dashboard-widget-card[data-widget-cols="4"] {
        grid-column: span 4 / span 4;
    }
    .dashboard-widget-card.col-span-6,
    .dashboard-widget-card[data-widget-cols="6"] {
        grid-column: span 6 / span 6;
    }
    .dashboard-widget-card.col-span-8,
    .dashboard-widget-card[data-widget-cols="8"] {
        grid-column: span 8 / span 8;
    }
    .dashboard-widget-card.col-span-12,
    .dashboard-widget-card[data-widget-cols="12"] {
        grid-column: span 12 / span 12;
    }
}

/* Modificadores de altura modular: 1x (min-h-[220px]) e 2x (min-h-[460px]) */
.dashboard-widget-card.h-1x,
.dashboard-widget-card[data-widget-height="1"] {
    min-height: 220px;
}
.dashboard-widget-card.h-2x,
.dashboard-widget-card[data-widget-height="2"] {
    min-height: 460px;
}

.dashboard-widget-card.is-resizing {
    outline: 2px solid #0284c7 !important;
    user-select: none !important;
    -webkit-user-select: none !important;
    z-index: 20;
}

/* Alça de redimensionamento no canto inferior direito */
.dashboard-widget-resize-handle {
    position: absolute;
    bottom: 4px;
    right: 4px;
    width: 22px;
    height: 22px;
    cursor: nwse-resize;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    background: transparent;
    border: none;
    padding: 0;
    border-radius: 4px;
    z-index: 10;
    touch-action: none;
    transition: color 0.15s ease, background-color 0.15s ease;
}
.dashboard-widget-resize-handle:hover,
.dashboard-widget-card.is-resizing .dashboard-widget-resize-handle {
    color: #0284c7;
    background-color: rgba(2, 132, 199, 0.12);
}

/* Dropdown popover de troca rápida de widget */
.dashboard-widget-switch-menu {
    position: absolute;
    top: 100%;
    right: 0;
    z-index: 30;
    margin-top: 0.25rem;
    width: 18rem;
    max-height: 20rem;
    overflow-y: auto;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 0.75rem;
    box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
    padding: 0.5rem;
}
.dashboard-widget-switch-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.5rem 0.75rem;
    border-radius: 0.5rem;
    font-size: 0.8125rem;
    font-weight: 500;
    color: #334155;
    text-align: left;
    transition: background-color 0.15s ease;
}
.dashboard-widget-switch-item:hover {
    background-color: #f1f5f9;
    color: #0284c7;
}
.dashboard-widget-switch-item.active {
    background-color: #f0f9ff;
    color: #0284c7;
    font-weight: 600;
}

/* req-236: tooltip stays above adjacent cards and expands into the cover. */
.dashboard-module-card:has(.dashboard-card-drag-handle:hover),
.dashboard-module-card:has(.dashboard-card-drag-handle:focus-visible) { position: relative; z-index: 100030; }
.dashboard-card-drag-handle::after { left: 0 !important; right: auto !important; transform: none !important; min-width: max-content; z-index: 100030 !important; }
.dashboard-module-card.has-cover .dashboard-card-svg { display: none !important; }
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-drag-handle,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-resize-handle,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-switch-btn,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-remove-btn { display: none !important; }
.dashboard-widget-resize-handle[data-corner="nw"] { top: 4px; left: 4px; bottom: auto; right: auto; }
.dashboard-widget-resize-handle[data-corner="ne"] { top: 4px; right: 4px; bottom: auto; cursor: nesw-resize; }
.dashboard-widget-resize-handle[data-corner="sw"] { bottom: 4px; left: 4px; right: auto; cursor: nesw-resize; }
.dashboard-options-menu { max-width: calc(100vw - 2rem); }
.dashboard-widget-card-body { display: flex; min-height: 0; }
.dashboard-widget-frame { width: 100%; height: 100%; min-height: 150px; border: 0; flex: 1; }

/* Dashboard Cards Component Styles */

.dashboard-cards-segment {
    margin: 0 !important;
    padding: 2em !important;
}

/* Update Notification Message */
.dashboard-update-message {
    margin-bottom: 1.5em !important;
    border-radius: 8px !important;
    animation: dashboard-update-pulse 2s ease-in-out infinite;
}

@keyframes dashboard-update-pulse {
    0%, 100% {
        box-shadow: 0 0 0 0 rgba(20, 163, 197, 0.4);
    }
    50% {
        box-shadow: 0 0 0 10px rgba(20, 163, 197, 0);
    }
}

.dashboard-update-message .header {
    font-size: 1.1em !important;
}

.dashboard-update-actions {
    margin-top: 1em;
    display: flex;
    gap: 0.5em;
    flex-wrap: wrap;
}

/* Header Row with Search */
.dashboard-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1em;
    margin-bottom: 1.5em;
}

.dashboard-header-row .dashboard-cards-title {
    margin-bottom: 0 !important;
}

.dashboard-search-container {
    min-width: 250px;
    max-width: 350px;
}

.dashboard-search-container input {
    border-radius: 4px 0 0 4px !important;
}

#dashboard-search-reset {
    background: rgb(17, 36, 64) !important;
    color: #fff !important;
}

#dashboard-search-reset:hover {
    background: rgb(20, 163, 197) !important;
}

/* Card hidden by search */
.dashboard-module-card.search-hidden {
    display: none !important;
}

/* No results message */
.dashboard-no-results {
    text-align: center;
    padding: 3em 1em;
    color: #7f8c8d;
    font-size: 1.1em;
    grid-column: 1 / -1;
    width: 100%;
}

.dashboard-no-results i {
    display: block;
    font-size: 3em;
    margin-bottom: 0.5em;
    color: #bdc3c7;
}

.dashboard-cards-title {
    margin-bottom: 1.5em !important;
    color: #2c3e50 !important;
}

/* Sortable Cards Container */
.dashboard-sortable-cards {
    min-height: 200px;
}

/* Module Card Styles */
.dashboard-module-card {
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
    cursor: default;
    position: relative;
}

.dashboard-module-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(21, 39, 64, 0.7) !important;
    filter: brightness(0.98);
}
.dashboard-module-card:hover .dashboard-card-header {
    background: rgba(20, 163, 197, 0.2) !important;
}

/* Drag Handle */
.dashboard-card-drag-handle {
    position: absolute;
    top: 8px;
    right: 8px;
    cursor: grab;
    color: #bdc3c7;
    opacity: 0;
    transition: opacity 0.2s ease;
    z-index: 10;
}

.dashboard-module-card:hover .dashboard-card-drag-handle {
    opacity: 1;
}

.dashboard-card-drag-handle:hover {
    color: #7f8c8d;
}

.dashboard-card-drag-handle:active {
    cursor: grabbing;
}

/* Card Header with SVG */
.dashboard-card-header {
    background: rgb(17, 36, 64);
    padding: 1.5em !important;
    text-align: center;
    position: relative;
}

.dashboard-card-svg {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 80px;
}

.dashboard-card-svg svg {
    width: 80px;
    height: 80px;
    fill: #fff;
    filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.2));
}

/* Card Title */
.dashboard-card-title {
    font-size: 1.5em !important;
    color: #2c3e50 !important;
    transition: color 0.2s ease;
}

.dashboard-card-title:hover {
    color: #667eea !important;
}

/* Card Meta */
.dashboard-card-meta {
    margin-top: 0.5em !important;
}

.dashboard-card-meta .category {
    font-size: 0.85em;
    color: #95a5a6;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Card Description */
.dashboard-card-description {
    margin-top: 1em !important;
    font-size: 1.2em;
    color: #7f8c8d;
    line-height: 1.5;
    min-height: 3em;
    max-height: 4.5em;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Card Actions */
.dashboard-card-actions {
    display: flex !important;
    justify-content: space-between;
    align-items: center;
    background: #f8f9fa !important;
}

/* Container para botões à direita (manual e docs) */
.dashboard-card-actions-right {
    display: flex;
    gap: 0.3em;
    margin-left: auto;
}

/* Botão de manual */
.dashboard-btn-manual {
    padding: 0.5em 0.7em !important;
}

/* Botão de documentação */
.dashboard-btn-docs {
    padding: 0.5em 0.7em !important;
}

/* SortableJS Classes */
.sortable-ghost {
    opacity: 0.7;
    background: #e8f4fd !important;
    border: 2px dashed #667eea !important;
}

.sortable-chosen {
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25) !important;
    transform: rotate(2deg);
}

.sortable-drag {
    opacity: 1 !important;
    cursor: grabbing !important;
}

/* Drop Placeholder */
.dashboard-card-placeholder {
    background: linear-gradient(135deg, #e8f4fd 0%, #f3e8ff 100%) !important;
    border: 2px dashed #667eea !important;
    border-radius: 0.28571429rem;
    min-height: 200px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dashboard-card-placeholder::after {
    content: '';
    width: 50px;
    height: 50px;
    border: 3px dashed #667eea;
    border-radius: 50%;
}

/* Logout Section */
.dashboard-cards-divider {
    margin: 2em 0 !important;
    color: #95a5a6 !important;
}

.dashboard-logout-segment {
    padding: 1em 0 !important;
}

/* Module Group Colors */
.dashboard-module-card[data-module-group="administrativo"] .dashboard-card-header {
    background: rgb(20, 163, 197);
}

.dashboard-module-card[data-module-group="usuarios"] .dashboard-card-header {
    background: rgb(20, 163, 197);
}

.dashboard-module-card[data-module-group="conteudo"] .dashboard-card-header {
    background: rgb(20, 163, 197);
}

.dashboard-module-card[data-module-group="configuracao"] .dashboard-card-header {
    background: rgb(20, 163, 197);
}

.dashboard-module-card[data-module-group="ecommerce"] .dashboard-card-header {
    background: rgb(20, 163, 197);
}

/* Responsive Adjustments */
@media only screen and (max-width: 767px) {
    .dashboard-card-drag-handle {
        opacity: 0.5;
    }
    
    .dashboard-card-svg svg {
        width: 60px;
        height: 60px;
    }
    
    .dashboard-card-description {
        display: none;
    }
}

/* Animation for card reordering */
@keyframes cardDrop {
    0% {
        transform: scale(1.05);
        opacity: 0.8;
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

.dashboard-module-card.just-dropped {
    animation: cardDrop 0.3s ease-out;
}
/* ========================================
   SVG Theme Colors
   ======================================== */

/* Tema Escuro (Padrão) */
.dashboard-card-svg svg,
.dashboard-card-svg.svg-theme-dark svg {
    fill: #2c3e50;
    stroke: #2c3e50;
}

.dashboard-card-svg.svg-theme-dark svg path[fill="currentColor"],
.dashboard-card-svg svg path[fill="currentColor"] {
    fill: #2c3e50;
}

/* Tema Claro */
.dashboard-card-svg.svg-theme-light svg {
    fill: #ffffff;
    stroke: #ffffff;
}

.dashboard-card-svg.svg-theme-light svg path[fill="currentColor"] {
    fill: #ffffff;
}

/* Tema Azul */
.dashboard-card-svg.svg-theme-blue svg {
    fill: #667eea;
    stroke: #667eea;
}

.dashboard-card-svg.svg-theme-blue svg path[fill="currentColor"] {
    fill: #667eea;
}

/* Override para SVGs dentro do header com fundo colorido - Feather Icons usa stroke */
.dashboard-card-header .dashboard-card-svg svg {
    stroke: rgb(20, 163, 197);
}

/* ========================================
   Drag-and-Drop Enhancements
   ======================================== */

/* Desabilitar seleção de texto durante arraste */
.is-dragging,
.is-dragging * {
    user-select: none !important;
    -webkit-user-select: none !important;
    -moz-user-select: none !important;
    -ms-user-select: none !important;
}

.dashboard-module-card.sortable-chosen,
.dashboard-module-card.sortable-drag {
    user-select: none !important;
    -webkit-user-select: none !important;
}

/* Impedir seleção no handle */
.dashboard-card-drag-handle {
    user-select: none;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
}

/* ========================================
   Responsividade Customizada para Tablets
   ======================================== */

/* Tablets (768px - 1024px): 2 colunas ao invés de 4 */
@media screen and (min-width: 768px) and (max-width: 1024px) {
    .dashboard-sortable-cards .ui.card {
        width: calc(50% - 1em) !important;
        margin-left: 0.5em !important;
        margin-right: 0.5em !important;
    }

    .dashboard-sortable-cards .ui.card:nth-child(odd) {
        margin-left: 0 !important;
    }

    .dashboard-sortable-cards .ui.card:nth-child(even) {
        margin-right: 0 !important;
    }
}

/* Tablets em orientação portrait (até 768px): 1 coluna */
@media screen and (max-width: 767px) {
    .dashboard-sortable-cards .ui.card {
        width: 100% !important;
        margin-left: 0 !important;
        margin-right: 0 !important;
    }
}

/* =========================================
   Dashboard 3D - A-Frame Styles
   ========================================= */

/* Container Principal */
#dashboard-3d-wrapper {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
}

/* Cena A-Frame */
#dashboard-3d-scene {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

/* =========================================
   Controles UI
   ========================================= */

#dashboard-3d-controls {
    position: fixed;
    top: 20px;
    left: 20px;
    z-index: 1000;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.control-btn {
    width: 48px;
    height: 48px;
    border: none;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    color: #fff;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
    text-decoration: none;
}

.control-btn:hover {
