}

.control-btn svg {
    width: 24px;
    height: 24px;
}

#nav-controls {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 20px;
}

/* =========================================
   Tooltip
   ========================================= */

#card-tooltip {
    position: fixed;
    padding: 16px 20px;
    background: rgba(20, 20, 40, 0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    z-index: 1000;
    pointer-events: none;
    max-width: 280px;
    transition: opacity 0.2s ease;
}

.tooltip-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}

.tooltip-icon {
    font-size: 24px;
}

.tooltip-title {
