}

.modal-description {
    color: #aaa;
    font-size: 14px;
    line-height: 1.5;
    margin: 0 0 20px 0;
}

.modal-buttons {
    display: flex;
    gap: 12px;
    margin-bottom: 15px;
}

.modal-btn {
    flex: 1;
    padding: 14px 20px;
    border: none;
    border-radius: 12px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 500;
