/* =========================================
   Menu Pizza
   ========================================= */

#pizza-menu {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 3000;
}

.pizza-backdrop {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.pizza-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 350px;
    height: 350px;
}

.pizza-center {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    background: linear-gradient(145deg, rgba(40, 40, 80, 0.9), rgba(20, 20, 50, 0.9));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    z-index: 10;
}

.pizza-close-btn {
    width: 50px;
    height: 50px;
    border: none;
    border-radius: 50%;
    background: rgba(255, 100, 100, 0.2);
    color: #ff6b6b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.pizza-close-btn:hover {
    background: rgba(255, 100, 100, 0.4);
    transform: scale(1.1);
}

.pizza-close-btn svg {
    width: 24px;
    height: 24px;
}

.pizza-items {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 100%;
    height: 100%;
}

.pizza-item {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y)));
    width: 70px;
    height: 70px;
    border: none;
    border-radius: 50%;
    background: linear-gradient(145deg, rgba(60, 60, 100, 0.9), rgba(30, 30, 60, 0.9));
    color: #fff;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.3);
    transition: all 0.3s ease;
    animation: pizzaItemIn 0.4s ease backwards;
}

.pizza-item:hover {
    background: linear-gradient(145deg, rgba(80, 80, 140, 0.9), rgba(40, 40, 80, 0.9));
    transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) scale(1.15);
    box-shadow: 0 8px 30px rgba(74, 158, 255, 0.3);
}

@keyframes pizzaItemIn {
    from {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0);
    }
    to {
        opacity: 1;
    }
}

.pizza-icon {
    font-size: 24px;
}

.pizza-label {
    position: absolute;
    top: -35px;
    white-space: nowrap;
    font-size: 12px;
    background: rgba(0, 0, 0, 0.8);
    padding: 4px 10px;
    border-radius: 6px;
    opacity: 0;
    transition: opacity 0.2s ease;
    pointer-events: none;
}

.pizza-item:hover .pizza-label {
    opacity: 1;
}

/* =========================================
   Container do Módulo (iframe)
   ========================================= */

#module-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #0a0a1a;
